    new=ctypes.c_ulonglong();ptr(0x4201,child,ctypes.byref(new));newpid=int(new.value);proof=confirm(child,newpid,event)
    eventlog.write(json.dumps(dict(utc=now(),**proof))+'\n');eventlog.flush();resume(child)
