namespace {
dtc_ag7::ProgressProducer ag7_progress;
}

accel_sim_framework::accel_sim_framework(std::string config_file,
                                          std::string trace_file) {
  std::cout << "Accel-Sim [build " << g_accelsim_version << "]";
  m_gpgpu_context = new gpgpu_context();

  // mimic argv
  unsigned argc = 5;
  const char *argv[] = {"accel-sim.out", "-config", config_file.c_str(),
                        "-trace", trace_file.c_str()};

  gpgpu_sim *m_gpgpu_sim =
      gpgpu_trace_sim_init_perf_model(argc, argv, m_gpgpu_context, &tconfig);
  m_gpgpu_sim->init();
  if (ag7_progress.enabled()) ag7_progress.observe("INIT",
      m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);

  tracer = trace_parser(tconfig.get_traces_filename());

  tconfig.parse_config();

  init();
  if (ag7_progress.enabled()) ag7_progress.observe("BOUNDARY",
      m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);
}

accel_sim_framework::accel_sim_framework(int argc, const char **argv) {
  std::cout << "Accel-Sim [build " << g_accelsim_version << "]";
  m_gpgpu_context = new gpgpu_context();

  m_gpgpu_sim =
      gpgpu_trace_sim_init_perf_model(argc, argv, m_gpgpu_context, &tconfig);
  m_gpgpu_sim->init();
  if (ag7_progress.enabled()) ag7_progress.observe("INIT",
      m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);

  tracer = trace_parser(tconfig.get_traces_filename());

  tconfig.parse_config();

  init();
  if (ag7_progress.enabled()) ag7_progress.observe("BOUNDARY",
      m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);
}

void accel_sim_framework::simulation_loop() {
  // for each kernel
  // load file
  // parse and create kernel info
  // launch
  // while loop till the end of the end kernel execution
  // prints stats

  bool ag7_limit_seen = false;  // Observer-only terminal classification.
  while (commandlist_index < commandlist.size() || !kernels_info.empty()) {
    if (ag7_progress.enabled()) ag7_progress.observe("PARSE",
        m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);
    parse_commandlist();
    if (ag7_progress.enabled()) ag7_progress.observe("BOUNDARY",
        m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);

    // Launch all kernels within window that are on a stream that isn't already
    // running
    for (auto k : kernels_info) {
      bool stream_busy = false;
      for (auto s : busy_streams) {
        if (s == k->get_cuda_stream_id()) stream_busy = true;
      }
      if (!stream_busy && m_gpgpu_sim->can_start_kernel() &&
          !k->was_launched()) {
        std::cout << "launching kernel name: " << k->get_name()
                  << " uid: " << k->get_uid()
                  << " cuda_stream_id: " << k->get_cuda_stream_id()
                  << std::endl;
        m_gpgpu_sim->launch(k);
        k->set_launched();
        busy_streams.push_back(k->get_cuda_stream_id());
        if (ag7_progress.enabled()) ag7_progress.observe("BOUNDARY",
            m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn,
            true, true, "NONE", static_cast<int64_t>(k->get_cuda_stream_id()));
      }
    }

    unsigned finished_kernel_uid = simulate();
    // cleanup finished kernel
    if (finished_kernel_uid || m_gpgpu_sim->cycle_insn_cta_max_hit() ||
        !m_gpgpu_sim->active()) {
      cleanup(finished_kernel_uid);
      if (ag7_progress.enabled()) ag7_progress.observe("BOUNDARY",
          m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true);
    }

    if (sim_cycles) {
      m_gpgpu_sim->update_stats();
      m_gpgpu_context->print_simulation_time();
    }

    if (m_gpgpu_sim->cycle_insn_cta_max_hit()) {
      ag7_limit_seen = true;
      printf(
          "GPGPU-Sim: ** break due to reaching the maximum cycles (or "
          "instructions) **\n");
      fflush(stdout);
      break;
    }
  }
  if (ag7_progress.enabled()) {
    const bool complete_candidate = !ag7_limit_seen &&
        commandlist_index == commandlist.size() && kernels_info.empty() &&
        !m_gpgpu_sim->cycle_insn_cta_max_hit();
    ag7_progress.observe("BOUNDARY",
        m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, true,
        ag7_limit_seen ? "LIMIT" :
            (complete_candidate ? "NATURAL" : "ERROR"));
  }
}

void accel_sim_framework::parse_commandlist() {
  // gulp up as many commands as possible - either cpu_gpu_mem_copy
  // or kernel_launch - until the vector "kernels_info" has reached
  // the window_size or we have read every command from commandlist
  while (kernels_info.size() < window_size && commandlist_index < commandlist.size()) {
    trace_kernel_info_t *kernel_info = NULL;
    if (commandlist[commandlist_index].m_type == command_type::cpu_gpu_mem_copy) {
      size_t addre, Bcount;
      tracer.parse_memcpy_info(commandlist[commandlist_index].command_string, addre, Bcount);
      std::cout << "launching memcpy command : "
                << commandlist[commandlist_index].command_string << std::endl;
      m_gpgpu_sim->perf_memcpy_to_gpu(addre, Bcount);
      commandlist_index++;
    } else if (commandlist[commandlist_index].m_type == command_type::kernel_launch) {
      // Read trace header info for window_size number of kernels
      kernel_trace_t *kernel_trace_info =
          tracer.parse_kernel_info(commandlist[commandlist_index].command_string);
      kernel_info = create_kernel_info(kernel_trace_info, m_gpgpu_context,
                                       &tconfig, &tracer);
      kernels_info.push_back(kernel_info);
      std::cout << "Header info loaded for kernel command : "
                << commandlist[commandlist_index].command_string << std::endl;
      commandlist_index++;
    } else {
      // unsupported commands will fail the simulation
      assert(0 && "Undefined Command");
    }
  }
}

void accel_sim_framework::cleanup(unsigned finished_kernel) {
  trace_kernel_info_t *k = NULL;
  unsigned long long finished_kernel_cuda_stream_id = -1;
  for (unsigned j = 0; j < kernels_info.size(); j++) {
    k = kernels_info.at(j);
    if (k->get_uid() == finished_kernel ||
        m_gpgpu_sim->cycle_insn_cta_max_hit() || !m_gpgpu_sim->active()) {
      for (unsigned int l = 0; l < busy_streams.size(); l++) {
        if (busy_streams.at(l) == k->get_cuda_stream_id()) {
          finished_kernel_cuda_stream_id = k->get_cuda_stream_id();
          busy_streams.erase(busy_streams.begin() + l);
          break;
        }
      }
      tracer.kernel_finalizer(k->get_trace_info());
      delete k->entry();
      delete k;
      kernels_info.erase(kernels_info.begin() + j);
      if (!m_gpgpu_sim->cycle_insn_cta_max_hit() && m_gpgpu_sim->active())
        break;
    }
  }
  if (k) {
    m_gpgpu_sim->print_stats(finished_kernel_cuda_stream_id);
    m_gpgpu_sim->perf_counters.print_counters();
  }
}

unsigned accel_sim_framework::simulate() {
  unsigned finished_kernel_uid = 0;
  do {
    if (!m_gpgpu_sim->active()) break;

    // performance simulation
    if (m_gpgpu_sim->active()) {
      m_gpgpu_sim->cycle();
      sim_cycles = true;
      // Same-thread post-cycle observation; no queue pops, model writes or
      // unsynchronized timer reads. Long blocking phases fail freshness upstream.
      if (ag7_progress.enabled()) ag7_progress.observe("SIMULATE",
          m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, false,
          "NONE", busy_streams.size() == 1 ?
              static_cast<int64_t>(busy_streams.front()) : -1);
      m_gpgpu_sim->deadlock_check();
    } else {
      if (m_gpgpu_sim->cycle_insn_cta_max_hit()) {
        m_gpgpu_context->the_gpgpusim->g_stream_manager
            ->stop_all_running_kernels();
        break;
      }
    }

    active = m_gpgpu_sim->active();
    finished_kernel_uid = m_gpgpu_sim->finished_kernel();
  } while (active && !finished_kernel_uid);
  return finished_kernel_uid;
}

trace_kernel_info_t *accel_sim_framework::create_kernel_info(kernel_trace_t *kernel_trace_info,
                                        gpgpu_context *m_gpgpu_context,
                                        trace_config *config,
                                        trace_parser *parser) {
  gpgpu_ptx_sim_info info;
  info.smem = kernel_trace_info->shmem;
  info.regs = kernel_trace_info->nregs;
  dim3 gridDim(kernel_trace_info->grid_dim_x, kernel_trace_info->grid_dim_y,
               kernel_trace_info->grid_dim_z);
  dim3 blockDim(kernel_trace_info->tb_dim_x, kernel_trace_info->tb_dim_y,
                kernel_trace_info->tb_dim_z);
  trace_function_info *function_info =
      new trace_function_info(info, m_gpgpu_context);
  function_info->set_name(kernel_trace_info->kernel_name.c_str());
  trace_kernel_info_t *kernel_info = new trace_kernel_info_t(
      gridDim, blockDim, function_info, parser, config, kernel_trace_info);

  return kernel_info;
}

gpgpu_sim *accel_sim_framework::gpgpu_trace_sim_init_perf_model(
    int argc, const char *argv[], gpgpu_context *m_gpgpu_context,
    trace_config *m_config) {
  srand(1);
  print_splash();

  option_parser_t opp = option_parser_create();

  m_gpgpu_context->ptx_reg_options(opp);
  m_gpgpu_context->func_sim->ptx_opcocde_latency_options(opp);

  icnt_reg_options(opp);

  m_gpgpu_context->the_gpgpusim->g_the_gpu_config =
      new gpgpu_sim_config(m_gpgpu_context);
  m_gpgpu_context->the_gpgpusim->g_the_gpu_config->reg_options(
      opp);  // register GPU microrachitecture options
  m_config->reg_options(opp);

  option_parser_cmdline(opp, argc, argv);  // parse configuration options
  fprintf(stdout, "GPGPU-Sim: Configuration options:\n\n");
  option_parser_print(opp, stdout);
  // Set the Numeric locale to a standard locale where a decimal point is a
  // "dot" not a "comma" so it does the parsing correctly independent of the
  // system environment variables
  assert(setlocale(LC_NUMERIC, "C"));
  m_gpgpu_context->the_gpgpusim->g_the_gpu_config->init();

  m_gpgpu_context->the_gpgpusim->g_the_gpu = new trace_gpgpu_sim(
      *(m_gpgpu_context->the_gpgpusim->g_the_gpu_config), m_gpgpu_context);

  m_gpgpu_context->the_gpgpusim->g_stream_manager =
      new stream_manager((m_gpgpu_context->the_gpgpusim->g_the_gpu),
                         m_gpgpu_context->func_sim->g_cuda_launch_blocking);

  m_gpgpu_context->the_gpgpusim->g_simulation_starttime = time((time_t *)NULL);

  return m_gpgpu_context->the_gpgpusim->g_the_gpu;
}

#ifndef ACCEL_SIM_AG7_POLICYB_PROGRESS_H
#define ACCEL_SIM_AG7_POLICYB_PROGRESS_H

// Experimental, default-OFF, observational producer. This header never receives
// a model pointer. Only the simulation thread supplies coherent scalar snapshots.
#include <cerrno>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <time.h>
#include <unistd.h>

namespace dtc_ag7 {
struct PreserveErrno {
  int saved = errno;
  ~PreserveErrno() { errno = saved; }
};
class ProgressProducer {
 public:
  ProgressProducer() {
    PreserveErrno preserve_errno;
    const char *opt_in = std::getenv("DTC_AG7_POLICY_B_PROGRESS");
    if (!opt_in || std::strcmp(opt_in, "1") != 0) return;
    // Invalid requested configurations emit nothing: the independently bound
    // receiver must reject absent/stale data. Never repair flags or model state.
    const char *fd = std::getenv("DTC_AG7_PROGRESS_FD");
    const char *generation = std::getenv("DTC_AG7_GENERATION");
    const char *input = std::getenv("DTC_AG7_INPUT_SHA");
    const char *roi = std::getenv("DTC_AG7_ROI_SHA");
    uint64_t descriptor = 0;
    if (!decimal(fd, descriptor) || descriptor < 3 || descriptor > 1048575 ||
        !token(generation) || !hex(input, 64) || !hex(roi, 64)) return;
    fd_ = static_cast<int>(descriptor);
    const int flags = fcntl(fd_, F_GETFL);
    int type = 0;
    socklen_t size = sizeof(type);
    sockaddr_un address{};
    socklen_t address_size = sizeof(address);
    if (flags < 0 || !(flags & O_NONBLOCK) ||
        getsockopt(fd_, SOL_SOCKET, SO_TYPE, &type, &size) != 0 ||
        (type != SOCK_DGRAM && type != SOCK_SEQPACKET) ||
        getsockname(fd_, reinterpret_cast<sockaddr *>(&address),
                    &address_size) != 0 || address.sun_family != AF_UNIX) return;
    pid_ = getpid();
    if (!read_start_ticks(start_ticks_)) return;
    std::memcpy(input_, input, 65);
    std::memcpy(roi_, roi, 65);
    std::strcpy(generation_, generation);
    enabled_ = true;
  }

  bool enabled() const { return enabled_; }

  // epoch=0 is the whole-input cumulative instruction epoch. phase_epoch only
  // identifies phase transitions; it NEVER resets a receiver's finite deadline.
  // stream_id=-1 means whole-input/multiple-or-no-active-stream, not stream zero.
  void observe(const char *phase, uint64_t completed, bool semantic_valid,
               bool force = false, const char *terminal = "NONE",
               int64_t stream_id = -1) {
    PreserveErrno preserve_errno;
    if (!enabled_) return;
    if (getpid() != pid_ || (semantic_valid && completed < last_completed_)) {
      enabled_ = false;
      return;
    }
    timespec ts{};
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0 || ts.tv_sec < 0) {
      enabled_ = false;
      return;
    }
    const uint64_t now = uint64_t(ts.tv_sec) * 1000000000ULL + ts.tv_nsec;
    if (now < last_clock_) { enabled_ = false; return; }
    last_clock_ = now;
    if (semantic_valid) last_completed_ = completed;
    if (std::strcmp(phase_, phase) != 0) {
      if (std::strlen(phase) >= sizeof(phase_)) {
        enabled_ = false;
        return;
      }
      std::strcpy(phase_, phase);
      ++phase_epoch_;
      force = true;
    }
    if (!force && emitted_ && now - last_emitted_ns_ < kCadenceNs) return;
    if (sequence_ >= kMaximumRecords) { enabled_ = false; return; }
    char packet[kMaximumPacket];
    const int bytes = std::snprintf(
        packet, sizeof(packet),
        "{\"v\":1,\"pid\":%ld,\"start_ticks\":%llu,"
        "\"generation\":\"%s\",\"input\":\"%s\",\"roi\":\"%s\","
        "\"seq\":%llu,\"mono_ns\":%llu,\"epoch\":0,"
        "\"phase_epoch\":%llu,\"phase\":\"%s\",\"stream_id\":%lld,"
        "\"stream_scope\":\"whole_input\",\"completed\":%llu,"
        "\"end\":\"%s\"}\n",
        static_cast<long>(pid_), static_cast<unsigned long long>(start_ticks_),
        generation_, input_, roi_,
        static_cast<unsigned long long>(sequence_ + 1),
        static_cast<unsigned long long>(now),
        static_cast<unsigned long long>(phase_epoch_), phase_,
        static_cast<long long>(stream_id),
        static_cast<unsigned long long>(completed), terminal);
    if (bytes < 0 || static_cast<size_t>(bytes) >= sizeof(packet)) {
      enabled_ = false;
      return;
    }
    // No retries, queue draining, disk writes, SIGPIPE, callbacks, state repair,
    // model writes or blocking transport. Missing data is fail-closed upstream.
    const ssize_t sent = send(fd_, packet, static_cast<size_t>(bytes),
                              MSG_DONTWAIT | MSG_NOSIGNAL);
    if (sent != bytes) { enabled_ = false; return; }
    ++sequence_;
    emitted_ = true;
    last_emitted_ns_ = now;
  }

 private:
  static constexpr uint64_t kCadenceNs = 10000000000ULL;
  static constexpr uint64_t kMaximumRecords = 8192;
  static constexpr size_t kMaximumPacket = 1024;
  static bool token(const char *text) {
    if (!text || !*text || std::strlen(text) > 64) return false;
    for (const char *p = text; *p; ++p)
      if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
            (*p >= '0' && *p <= '9') || *p == '-' || *p == '_' ||
            *p == '.' || *p == ':')) return false;
    return true;
  }
  static bool decimal(const char *text, uint64_t &out) {
    if (!text || !*text || std::strlen(text) > 20) return false;
    uint64_t value = 0;
    for (const char *p = text; *p; ++p) {
      if (*p < '0' || *p > '9') return false;
      const unsigned digit = unsigned(*p - '0');
      if (value > (UINT64_MAX - digit) / 10) return false;
      value = value * 10 + digit;
    }
    out = value;
    return true;
  }
  static bool hex(const char *text, size_t length) {
    if (!text || std::strlen(text) != length) return false;
    for (size_t i = 0; i < length; ++i)
      if (!((text[i] >= '0' && text[i] <= '9') ||
            (text[i] >= 'a' && text[i] <= 'f'))) return false;
    return true;
  }
  static bool read_start_ticks(uint64_t &out) {
    const int fd = open("/proc/self/stat", O_RDONLY | O_CLOEXEC);
    if (fd < 0) return false;
    char data[4096];
    const ssize_t bytes = read(fd, data, sizeof(data) - 1);
    close(fd);
    if (bytes <= 0 || bytes >= static_cast<ssize_t>(sizeof(data) - 1)) return false;
    data[bytes] = '\0';
    char *p = std::strrchr(data, ')');
    if (!p || p[1] != ' ') return false;
    p += 2;  // field 3 (state), after the parenthesized comm field.
    for (unsigned field = 3; field < 22; ++field) {
      p = std::strchr(p, ' ');
      if (!p) return false;
      ++p;
    }
    char *end = std::strchr(p, ' ');
    if (!end) return false;
    *end = '\0';
    return decimal(p, out) && out > 0;
  }
  bool enabled_ = false;
  bool emitted_ = false;
  int fd_ = -1;
  pid_t pid_ = 0;
  uint64_t start_ticks_ = 0, sequence_ = 0;
  uint64_t last_clock_ = 0, last_emitted_ns_ = 0, last_completed_ = 0;
  uint64_t phase_epoch_ = 0;
  char input_[65]{}, roi_[65]{}, generation_[65]{}, phase_[32]{};
};
